import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for f in glob.glob('programs/task-2db4f19c.*'): print(f)

def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    line=cnt.most_common()[-1][0]
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==line]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    rowline={r for r in range(h) if r in (r0,r1) or any(g[r][c]==line and g[r][c+1]==line for c in range(w-1))}
    colline={c for c in range(w) if c in (c0,c1) or any(g[r][c]==line and g[r+1][c]==line for r in range(h-1))}
    out=[r[:] for r in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=line:
                if r in rowline and c0<=c<=c1: out[r][c]=2
                elif c in colline and r0<=r<=r1: out[r][c]=2
                elif r in rowline and any(g[r][k]==line for k in range(c)) and any(g[r][k]==line for k in range(c+1,w)): out[r][c]=2
                elif c in colline and any(g[k][c]==line for k in range(r)) and any(g[k][c]==line for k in range(r+1,h)): out[r][c]=2
    return out
res=[f(G[f'Demo pair {i} input'])==G[f'Demo pair {i} output'] for i in (1,2,3)]
print(res)
if all(res):
